import json
with open('baseline-packages.json') as f: before = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs[p['id']] = p.get('resolvedVersion', p.get('requestedVersion',''))
        result[name] = pkgs
    return result

b, a = get_pkgs(before), get_pkgs(after)
changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp, ap = b.get(proj,{}), a.get(proj,{})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv, av = bp.get(pkg,'—'), ap.get(pkg,'—')
        if bv != av:
            changes.append((proj, pkg, bv, av))
if changes:
    print('Changes detected:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj}: {pkg} {bv} -> {av}')
else:
    print('No unexpected changes (but version alignment is expected)')
# Show all resolved versions
print()
for proj in sorted(a.keys()):
    for pkg, ver in sorted(a[proj].items()):
        bv = b.get(proj,{}).get(pkg,'—')
        flag = ' (CHANGED)' if bv != ver else ''
        print(f'{proj}: {pkg} = {ver}{flag}')
"

